{"code":"import pandas as pd, statsmodels.formula.api as smf
x=pd.read_csv('data/explore.csv').dropna(subset=['tensile_mpa'])
cols=['anneal_temp','cool_rate','carbon_pct','chromium_pct','grain_size','humidity','press_time','nickel_pct','porosity','cure_hours']
for c in cols:
 d=x.dropna(subset=[c]); m=smf.ols(f'tensile_mpa ~ {c} + C(lab)',d).fit()
 print(c, round(m.params[c],4), round(m.pvalues[c],5), round(m.rsquared,3),len(d))"}

